// Package netpol renders the NetworkPolicies of the platform from its manifests.
package netpol

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"reflect"
	"regexp"
	"slices"
	"strconv"
	"strings"

	"go.yaml.in/yaml/v3"
)

// File is the generated file, beside the manifests it is rendered from.
const File = "networkpolicies.yaml"

var broker = regexp.MustCompile(`^([a-z0-9]([a-z0-9-]*[a-z0-9])?)-kafka-bootstrap\.([a-z0-9]([a-z0-9-]*[a-z0-9])?)\.svc:([0-9]+)$`)

type labels struct {
	MatchLabels map[string]string `yaml:"matchLabels,omitempty"`
}

type peer struct {
	NamespaceSelector labels `yaml:"namespaceSelector"`
	PodSelector       labels `yaml:"podSelector"`
}

type port struct {
	Protocol string `yaml:"protocol"`
	Port     int    `yaml:"port"`
}

type egress struct {
	To    []peer `yaml:"to"`
	Ports []port `yaml:"ports"`
}

type policy struct {
	APIVersion string `yaml:"apiVersion"`
	Kind       string `yaml:"kind"`
	Metadata   struct {
		Name string `yaml:"name"`
	} `yaml:"metadata"`
	Spec struct {
		PodSelector labels   `yaml:"podSelector"`
		PolicyTypes []string `yaml:"policyTypes"`
		Egress      []egress `yaml:"egress,omitempty"`
	} `yaml:"spec"`
}

type workload struct {
	Spec struct {
		Template struct {
			Spec struct {
				Containers []struct {
					Env []struct {
						Name  string `yaml:"name"`
						Value string `yaml:"value"`
					} `yaml:"env"`
				} `yaml:"containers"`
			} `yaml:"spec"`
		} `yaml:"template"`
	} `yaml:"spec"`
}

func newPolicy(name string, selector map[string]string, types ...string) policy {
	var p policy
	p.APIVersion, p.Kind, p.Metadata.Name = "networking.k8s.io/v1", "NetworkPolicy", name
	p.Spec.PodSelector.MatchLabels, p.Spec.PolicyTypes = selector, types
	return p
}

func to(namespace string, pod map[string]string, ports ...port) egress {
	return egress{To: []peer{{labels{map[string]string{"kubernetes.io/metadata.name": namespace}}, labels{pod}}}, Ports: ports}
}

// Render reads every manifest of fsys but File and renders the namespace's default deny, the DNS egress of every pod,
// and the egress of each workload to the stores its variables name: Postgres for POSTGRES_URL, each Strimzi cluster of
// KAFKA_BROKERS.
func Render(fsys fs.FS) ([]byte, error) {
	dns := newPolicy("dns", nil, "Egress")
	dns.Spec.Egress = []egress{to("kube-system", map[string]string{"k8s-app": "kube-dns"}, port{"UDP", 53}, port{"TCP", 53})}
	policies := []policy{newPolicy("default-deny", nil, "Ingress", "Egress"), dns}
	names, err := fs.Glob(fsys, "*.yaml")
	if err != nil {
		return nil, err
	}
	for _, file := range names {
		if file == File {
			continue
		}
		p, err := flows(fsys, file)
		if err != nil {
			return nil, err
		}
		if len(p.Spec.Egress) > 0 {
			policies = append(policies, p)
		}
	}
	var b bytes.Buffer
	b.WriteString("# Code generated by tools/netpol from deploy/k8s; DO NOT EDIT.\n")
	enc := yaml.NewEncoder(&b)
	enc.SetIndent(2)
	for _, p := range policies {
		if err := enc.Encode(p); err != nil {
			return nil, err
		}
	}
	return b.Bytes(), enc.Close()
}

func flows(fsys fs.FS, file string) (policy, error) {
	name := strings.TrimSuffix(file, ".yaml")
	p := newPolicy(name, map[string]string{"app.kubernetes.io/name": name}, "Egress")
	data, err := fs.ReadFile(fsys, file)
	if err != nil {
		return p, err
	}
	dec := yaml.NewDecoder(bytes.NewReader(data))
	for {
		var w workload
		if err := dec.Decode(&w); errors.Is(err, io.EOF) {
			return p, nil
		} else if err != nil {
			return p, fmt.Errorf("%s: %w", file, err)
		}
		for _, c := range w.Spec.Template.Spec.Containers {
			for _, e := range c.Env {
				switch e.Name {
				case "POSTGRES_URL":
					p.Spec.Egress = append(p.Spec.Egress, to("postgres", map[string]string{"cnpg.io/cluster": "postgres"}, port{"TCP", 5432}))
				case "KAFKA_BROKERS":
					for b := range strings.SplitSeq(e.Value, ",") {
						m := broker.FindStringSubmatch(strings.TrimSpace(b))
						if m == nil {
							return p, fmt.Errorf("%s: broker %q is not <cluster>-kafka-bootstrap.<namespace>.svc:<port>", name, b)
						}
						n, err := strconv.Atoi(m[5])
						if err != nil {
							return p, fmt.Errorf("%s: broker %q: %w", name, b, err)
						}
						if f := to(m[3], map[string]string{"strimzi.io/cluster": m[1]}, port{"TCP", n}); !slices.ContainsFunc(p.Spec.Egress, func(e egress) bool {
							return reflect.DeepEqual(e, f)
						}) {
							p.Spec.Egress = append(p.Spec.Egress, f)
						}
					}
				}
			}
		}
	}
}
